const cp = require('child_process');
const branch = process.env.BRANCH_NAME;
const remote = process.env.REMOTE_NAME;
const r = cp.spawnSync('git', ['push', '-u', remote, branch], {encoding: 'utf8', maxBuffer: 20 * 1024 * 1024});
if (r.error) throw r.error;
if (r.status !== 0) throw new Error(`git push failed (${r.status}): ${r.stderr || r.stdout}`);
process.stdout.write((r.stdout || r.stderr || `Pushed ${branch}`).trim());

const fs = require('fs');
const cp = require('child_process');
const draft = JSON.parse(fs.readFileSync(0, 'utf8'));
const r = cp.spawnSync('gh', ['pr', 'create', '--base', process.env.BASE_BRANCH, '--head', process.env.BRANCH_NAME, '--title', draft.title, '--body', draft.body], {encoding: 'utf8', maxBuffer: 20 * 1024 * 1024});
if (r.error) throw r.error;
if (r.status !== 0) throw new Error(`gh pr create failed (${r.status}): ${r.stderr || r.stdout}`);
process.stdout.write((r.stdout || '').trim());
